import json, re, random, sys, time
import chess

RULES = json.load(open("/tmp/obench-cell-zky3ddvf/bench_opencode_regex-chess_l6hpjar2/re.json"))


def run(fen):
    for p, r in RULES:
        fen = re.sub(p, r, fen)
    return fen.split("\n")


def expected(fen):
    b = chess.Board(fen)
    s = set()
    for m in b.legal_moves:
        if m.promotion and m.promotion != chess.QUEEN:
            continue
        c = b.copy(); c.push(m)
        s.add(" ".join(c.fen().split(" ")[:-2]))
    return s


def check(fen):
    ours = [" ".join(x.split(" ")[:-2]) for x in run(fen)]
    exp = expected(fen)
    ok = len(ours) == len(exp) and all(x in exp or x.rpartition(" ")[0] + " -" in exp for x in ours)
    if not ok:
        print("FAIL", fen)
        print(" extra:", [x for x in ours if not (x in exp or x.rpartition(" ")[0] + " -" in exp)])
        print(" missing:", exp - set(ours) - {x.rpartition(" ")[0] + " -" for x in ours})
        print(" counts", len(ours), len(exp))
    return ok


ex = "<REDACTED_B64> w kq - 0 1"
print(run(ex))
random.seed(int(sys.argv[1]) if len(sys.argv) > 1 else 0)
n = 0; fails = 0; t = time.time()
for g in range(int(sys.argv[2]) if len(sys.argv) > 2 else 200):
    b = chess.Board()
    while not b.is_game_over() and b.ply() < 300:
        if b.turn == chess.WHITE:
            n += 1
            if not check(b.fen()):
                fails += 1
                if fails > 5: sys.exit(1)
        moves = list(b.legal_moves)
        # bias towards captures/promotions/castling a bit
        pref = [m for m in moves if b.is_castling(m) or b.is_en_passant(m) or m.promotion]
        b.push(random.choice(pref) if pref and random.random() < 0.7 else random.choice(moves))
print("positions", n, "fails", fails, "time", time.time() - t)
